static void processPersistence(const fs::path& executable){
    Workspace work;auto root=work.path/"process shared";{ark::ProjectMemory initialize(config(root));}
#ifdef _WIN32
    std::vector<HANDLE> children;for(int i=0;i<3;++i){auto command=L"\""+executable.wstring()+L"\" --memory-child \""+root.wstring()+L"\"";STARTUPINFOW startup{};startup.cb=sizeof(startup);PROCESS_INFORMATION process{};check(CreateProcessW(nullptr,command.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,nullptr,&startup,&process)!=FALSE,"launch independent memory worker process");CloseHandle(process.hThread);children.push_back(process.hProcess);}for(auto child:children){DWORD code=1;check(WaitForSingleObject(child,20000)==WAIT_OBJECT_0&&GetExitCodeProcess(child,&code)&&code==0,"independent memory process committed through real SQLite");CloseHandle(child);}
#else
    std::vector<pid_t> children;for(int i=0;i<3;++i){auto child=fork();check(child>=0,"fork memory process");if(child==0){auto exe=utf8(executable),path=utf8(root);execl(exe.c_str(),exe.c_str(),"--memory-child",path.c_str(),(char*)nullptr);_exit(127);}children.push_back(child);}for(auto child:children){int status=0;check(waitpid(child,&status,0)==child&&WIFEXITED(status)&&WEXITSTATUS(status)==0,"independent process committed through real SQLite");}
#endif
    ark::ProjectMemory reopened(config(root));check(call(reopened,"stats").find("records")->num==1&&first(call(reopened,"get",getArgs())).find("revision")->num==1,"multiple real processes share idempotent storage after restart");
}
class FixtureEmbeddings final:public ark::MemoryEmbeddingProvider {
public:
    std::string fingerprint="synthetic-fixture-model-a";bool ready=true;
    ark::MemoryEmbedding embed(const std::string& text) override{if(!ready)throw std::runtime_error("synthetic embedding unavailable");bool car=text.find("automobile")!=std::string::npos||text.find("vehicle")!=std::string::npos;bool dog=text.find("canine")!=std::string::npos;std::vector<float> values(64);for(int i=0;i<32;++i){float value=(float)std::sin(i*1.13+.5);if(car||(!car&&!dog))values[(std::size_t)i]=value;if(dog||(!car&&!dog))values[(std::size_t)i+32]=value;}return {values,fingerprint};}
    V health() const override{V out=V::makeObj();out.set("ready",V::makeBool(ready));out.set("fixture",V::makeBool(true));return out;}
};
