    {ark::ProjectMemory migrated(config(work.path));auto row=first(call(migrated,"get",getArgs()));check(row.find("revision")->num==1&&row.find("created_by")->str=="legacy:author"&&row.find("state")->str=="promoted"&&row.find("facts")->arr.empty(),"schema migration preserves source, attribution and revision while adding explicit defaults");check(call(migrated,"store",declaration()).find("deduplicated")->b,"legacy declarations remain idempotent after default-field migration");check(call(migrated,"search",json(R"({"text":"wheelbase"})")).find("records")->arr.size()==1,"legacy lexical facts remain searchable after vector schema migration");}
