static double milliseconds(std::chrono::steady_clock::time_point start){return std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();}
static V timings(std::vector<double> samples){std::sort(samples.begin(),samples.end());V out=V::makeObj();out.set("samples",V::makeNum((double)samples.size()));out.set("p50_ms",V::makeNum(samples[(samples.size()-1)/2]));out.set("p95_ms",V::makeNum(samples[(std::size_t)((samples.size()-1)*.95)]));return out;}
static void benchmark(const std::string& output){
    Workspace work;auto cfg=config(work.path);ark::ProjectMemory memory(cfg);const std::string project="synthetic:shared-memory-performance-v1";V history=V::makeArr();auto began=std::chrono::steady_clock::now();
    for(int i=0;i<300;++i){auto key="case "+std::to_string(i),content="Synthetic retained decision for case "+std::to_string(i)+". Keep the authored design editable, preserve the measured source and inspect the current revision before applying any change. This fixture records an attributed historical decision, not a manufacturing certificate. "+std::string(256,'x');auto args=declaration(key,content);args.set("title",V::makeStr("Synthetic case "+std::to_string(i)));args.set("source",V::makeStr("synthetic:fixture:"+std::to_string(i)));args.set("source_fingerprint",V::makeStr(ark::iterationSha256(content)));call(memory,"store",args,project);V get=getArgs(key);auto receipt=call(memory,"get",get,project);V request=V::makeObj();request.set("type",V::makeStr("function_call"));request.set("name",V::makeStr("memory_context"));request.set("call_id",V::makeStr("synthetic-read-"+std::to_string(i)));request.set("arguments",V::makeStr(get.dump()));history.arr.push_back(request);V response=V::makeObj();response.set("type",V::makeStr("function_call_output"));response.set("call_id",V::makeStr("synthetic-read-"+std::to_string(i)));response.set("output",V::makeStr(receipt.dump()));history.arr.push_back(response);}
    const double seedMs=milliseconds(began);auto query=json(R"({"text":"case 123","limit":3})");auto selected=call(memory,"search",query,project);check(selected.find("records")->arr.size()==1&&first(selected).find("key")->str=="case 123","benchmark retrieves the exact relevant persisted synthetic decision");const auto historyBytes=history.dump().size(),selectedBytes=selected.dump().size();check(history.dump().find(first(selected).find("content")->str)!=std::string::npos&&selectedBytes<historyBytes,"both serialized strategies retain the same relevant fact");std::vector<double> fullTimes,selectedTimes;
    for(int i=0;i<35;++i){began=std::chrono::steady_clock::now();auto full=history.dump();auto fullMs=milliseconds(began);began=std::chrono::steady_clock::now();auto recalled=call(memory,"search",query,project).dump();auto selectedMs=milliseconds(began);check(full.size()==historyBytes&&recalled.size()==selectedBytes,"measured strategies preserve actual serialized byte counts");if(i>=5){fullTimes.push_back(fullMs);selectedTimes.push_back(selectedMs);}}
    std::vector<double> coldTimes;for(int i=0;i<5;++i){began=std::chrono::steady_clock::now();ark::ProjectMemory reopened(cfg);auto response=call(reopened,"search",query,project);auto elapsed=milliseconds(began);check(first(response).find("key")->str=="case 123","cold instance recalls persisted fixture");coldTimes.push_back(elapsed);}
    std::vector<std::unique_ptr<ark::ProjectMemory>> agents;for(int i=0;i<4;++i)agents.push_back(std::make_unique<ark::ProjectMemory>(cfg));std::vector<std::vector<double>> parallelTimes(4);std::vector<std::thread> workers;std::atomic_int failures=0;for(int i=0;i<4;++i)workers.emplace_back([&,i]{for(int sample=0;sample<20;++sample){auto start=std::chrono::steady_clock::now();try{auto response=call(*agents[i],"search",query,project);if(response.find("records")->arr.size()!=1||first(response).find("key")->str!="case 123")++failures;parallelTimes[i].push_back(milliseconds(start));}catch(...){++failures;}}});for(auto& worker:workers)worker.join();check(failures==0,"all concurrent persisted-recall samples returned the same exact relevant fact");std::vector<double> parallel;for(const auto& values:parallelTimes)parallel.insert(parallel.end(),values.begin(),values.end());
    V receipt=V::makeObj();receipt.set("format",V::makeStr("ark-project-memory-performance-v1"));receipt.set("fixture",V::makeStr("300 synthetic attributed records; no user drawings, conversation files or credentials"));receipt.set("records",V::makeNum(300));receipt.set("sqlite_version",V::makeStr(sqlite3_libversion()));receipt.set("retrieval_mode",V::makeStr("lexical_fts5"));receipt.set("seed_and_readback_ms",V::makeNum(seedMs));receipt.set("full_history_bytes",V::makeNum((double)historyBytes));receipt.set("selected_recall_bytes",V::makeNum((double)selectedBytes));receipt.set("full_history_serialization",timings(fullTimes));receipt.set("warm_selected_recall_and_serialization",timings(selectedTimes));receipt.set("cold_open_and_selected_recall",timings(coldTimes));receipt.set("four_connection_parallel_recall",timings(parallel));receipt.set("parallel_agents",V::makeNum(4));receipt.set("failed_attempts",V::makeNum(failures.load()));receipt.set("baseline_scope",V::makeStr("Serialize all 300 synthetic historical read exchanges versus retrieve and serialize the one same relevant persisted fact. This is bounded local context transport, not an equivalent complete-history content contract or a model task comparison."));receipt.set("exclusions",V::makeStr("No model/provider requests, embeddings, code graph extraction, CAD evaluation, live tokens, price, design quality, end-to-end agent workload or memXT comparison."));receipt.set("superiority_claim",V::makeBool(false));auto bytes=receipt.dump();std::cout<<"PROJECT_MEMORY_PERFORMANCE "<<bytes<<'\n';if(!output.empty()){std::ofstream file(fs::u8path(output),std::ios::binary);file<<bytes;check((bool)file,"write bounded synthetic performance receipt");}
}
